/** سرویس LMS بزرگسالان با RBAC تازه، optimistic concurrency و تاریخچه append-only بدون PII/محتوا. */
import { env } from "cloudflare:workers";
import type { AccountContext } from "@/lib/accounts";
import type { AccountPermission } from "@/lib/phase3b-policy";

export const COURSE_STATUSES = ["DRAFT", "ACTIVE", "ARCHIVED"] as const;
export const CLASS_STATUSES = ["DRAFT", "ACTIVE", "CLOSED"] as const;
export const LESSON_STATUSES = ["DRAFT", "PUBLISHED", "ARCHIVED"] as const;
export const ENROLLMENT_STATUSES = ["ACTIVE", "COMPLETED", "WITHDRAWN"] as const;
export const LIFECYCLE_REASON_CODES = ["CONTENT_READY", "TEMPORARY_PAUSE", "ADMIN_CORRECTION", "PROGRAM_CLOSED", "ENROLLMENT_COMPLETED", "ENROLLMENT_WITHDRAWN", "RE_ENROLLMENT", "INSTRUCTOR_CHANGED"] as const;
export const LIFECYCLE_RESOURCE_TYPES = ["COURSE", "CLASS", "LESSON", "ENROLLMENT", "INSTRUCTOR_ASSIGNMENT"] as const;
export type CourseStatus = (typeof COURSE_STATUSES)[number];
export type ClassStatus = (typeof CLASS_STATUSES)[number];
export type LessonStatus = (typeof LESSON_STATUSES)[number];
export type EnrollmentStatus = (typeof ENROLLMENT_STATUSES)[number];
export type LifecycleReasonCode = (typeof LIFECYCLE_REASON_CODES)[number];
export type LifecycleResourceType = (typeof LIFECYCLE_RESOURCE_TYPES)[number];

export type LmsCourse = { courseId: string; title: string; status: CourseStatus; version: number; activatedAt: string | null; archivedAt: string | null; updatedAt: string };
export type LmsClass = { classId: string; courseId: string; title: string; status: ClassStatus; version: number; activatedAt: string | null; closedAt: string | null; updatedAt: string; courseTitle?: string };
export type LmsLesson = { lessonId: string; courseId: string; title: string; bodyText: string; position: number; status: LessonStatus; version: number; publishedAt: string | null; archivedAt: string | null; publishedRevisionId?: string | null; updatedAt: string; courseTitle?: string };
export type LessonRevision = { revisionId: string; lessonId: string; title: string; bodyText: string; createdByAccountId: string; createdAt: string; lastPublishedAt: string | null };
export type LmsAssignment = { assignmentId: string; classId: string; instructorAccountId: string; assignedAt: string; version: 1 };
export type LmsEnrollment = { enrollmentId: string; classId: string; studentAccountId: string; status: EnrollmentStatus; version: number; completedAt: string | null; withdrawnAt: string | null; updatedAt: string };
export type EligibleAccount = { accountId: string };
export type LmsPage<T> = { items: T[]; nextOffset: number | null };
export type LifecycleEventView = { eventId: string; resourceType: LifecycleResourceType; resourceId: string; fromStatus: string | null; toStatus: string; reasonCode: string; resourceVersion: number; actorAccountId: string; occurredAt: string };
export type AdminLmsOverview = {
  courses: LmsCourse[]; classes: LmsClass[]; lessons: LmsLesson[]; assignments: LmsAssignment[]; enrollments: LmsEnrollment[];
  instructors: EligibleAccount[]; students: EligibleAccount[];
  nextCourseOffset: number | null; nextClassOffset: number | null; nextLessonOffset: number | null; nextAssignmentOffset: number | null; nextEnrollmentOffset: number | null;
};
export type AdminLmsOffsets = { course: number; class: number; lesson: number; assignment: number; enrollment: number };

type OperationResult<T = undefined> = { ok: true; value: T } | { ok: false; code: string };
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
const LMS_PERMISSIONS: readonly AccountPermission[] = ["courses.manage", "classes.manage", "classes.assign_instructor", "enrollments.manage"];
const HISTORY_PERMISSION: Record<LifecycleResourceType, AccountPermission> = { COURSE: "courses.manage", CLASS: "classes.manage", LESSON: "courses.manage", ENROLLMENT: "enrollments.manage", INSTRUCTOR_ASSIGNMENT: "classes.assign_instructor" };

function isTransitionReasonAllowed(resourceType: LifecycleResourceType, fromStatus: string, toStatus: string, reasonCode: LifecycleReasonCode): boolean {
  if (resourceType === "ENROLLMENT") {
    if (fromStatus === "ACTIVE" && toStatus === "COMPLETED") return reasonCode === "ENROLLMENT_COMPLETED" || reasonCode === "ADMIN_CORRECTION";
    if (fromStatus === "ACTIVE" && toStatus === "WITHDRAWN") return reasonCode === "ENROLLMENT_WITHDRAWN" || reasonCode === "ADMIN_CORRECTION";
    if (fromStatus === "COMPLETED" && toStatus === "ACTIVE") return reasonCode === "ADMIN_CORRECTION";
    if (fromStatus === "WITHDRAWN" && toStatus === "ACTIVE") return reasonCode === "RE_ENROLLMENT" || reasonCode === "ADMIN_CORRECTION";
    return false;
  }
  if (resourceType === "INSTRUCTOR_ASSIGNMENT") return fromStatus === "ASSIGNED" && toStatus === "REVOKED" && (reasonCode === "INSTRUCTOR_CHANGED" || reasonCode === "ADMIN_CORRECTION");
  const validCourse = resourceType === "COURSE" && ((fromStatus === "DRAFT" && (toStatus === "ACTIVE" || toStatus === "ARCHIVED")) || (fromStatus === "ACTIVE" && (toStatus === "DRAFT" || toStatus === "ARCHIVED")));
  const validClass = resourceType === "CLASS" && ((fromStatus === "DRAFT" && (toStatus === "ACTIVE" || toStatus === "CLOSED")) || (fromStatus === "ACTIVE" && (toStatus === "DRAFT" || toStatus === "CLOSED")));
  const validLesson = resourceType === "LESSON" && ((fromStatus === "DRAFT" && (toStatus === "PUBLISHED" || toStatus === "ARCHIVED")) || (fromStatus === "PUBLISHED" && (toStatus === "DRAFT" || toStatus === "ARCHIVED")));
  if (!validCourse && !validClass && !validLesson) return false;
  if (reasonCode === "ADMIN_CORRECTION") return true;
  if (toStatus === "ACTIVE" || toStatus === "PUBLISHED") return reasonCode === "CONTENT_READY";
  if (toStatus === "DRAFT") return reasonCode === "TEMPORARY_PAUSE";
  return reasonCode === "PROGRAM_CLOSED";
}

function requireDb(): D1Database { if (!env.DB) throw new Error("D1 binding DB is unavailable"); return env.DB; }
export function isLmsId(value: string): boolean { return UUID_PATTERN.test(value); }
function pageOffset(value: number): number { return Number.isSafeInteger(value) && value >= 0 ? value : 0; }

/* نقش ADMIN میان‌بر نیست؛ نقش، حساب فعال و permission در هر درخواست دوباره از D1 خوانده می‌شوند. */
async function hasFreshPermission(accountId: string, permission: AccountPermission): Promise<boolean> {
  if (!LMS_PERMISSIONS.includes(permission)) return false;
  const row = await requireDb().prepare(`SELECT 1 AS allowed FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id
    WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code=? AND p.revoked_at IS NULL LIMIT 1`).bind(accountId, permission).first<{ allowed: number }>();
  return row?.allowed === 1;
}
async function hasAnyFreshLmsPermission(accountId: string): Promise<boolean> {
  const row = await requireDb().prepare(`SELECT 1 AS allowed FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id
    WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code IN ('courses.manage','classes.manage','classes.assign_instructor','enrollments.manage') AND p.revoked_at IS NULL LIMIT 1`).bind(accountId).first<{ allowed: number }>();
  return row?.allowed === 1;
}

/* ویرایش محتوا و audit در یک batch اتمیک‌اند؛ lifecycle event برای ویرایش محتوا ساخته نمی‌شود. */
async function runAuditedMutation(db: D1Database, mutation: D1PreparedStatement, actor: AccountContext, actionCode: string, targetType: string, targetId: string, reasonCode: string, requestId: string, occurredAt: string): Promise<number> {
  const audit = db.prepare(`INSERT INTO audit_events (audit_event_id,actor_account_id,action_code,target_type,target_id,outcome_code,reason_code,request_id,occurred_at)
    SELECT ?,?,?,?,?,'SUCCEEDED',?,?,? WHERE changes()=1`).bind(crypto.randomUUID(), actor.accountId, actionCode, targetType, targetId, reasonCode, requestId, occurredAt);
  const [result] = await db.batch([mutation, audit]); return result.meta.changes ?? 0;
}
/* mutation، رخداد چرخه عمر و audit یک واحد اتمیک‌اند؛ هیچ متن درس یا شناسه دانشجو در event payload نیست. */
async function runLifecycleMutation(db: D1Database, mutation: D1PreparedStatement, actor: AccountContext, event: { resourceType: LifecycleResourceType; resourceId: string; fromStatus: string | null; toStatus: string; reasonCode: string; version: number }, actionCode: string, targetType: string, requestId: string, occurredAt: string): Promise<number> {
  const lifecycleEvent = db.prepare(`INSERT INTO lms_lifecycle_events (lifecycle_event_id,resource_type,resource_id,from_status,to_status,reason_code,resource_version,actor_account_id,request_id,occurred_at)
    SELECT ?,?,?,?,?,?,?,?,?,? WHERE changes()=1`).bind(crypto.randomUUID(), event.resourceType, event.resourceId, event.fromStatus, event.toStatus, event.reasonCode, event.version, actor.accountId, requestId, occurredAt);
  const audit = db.prepare(`INSERT INTO audit_events (audit_event_id,actor_account_id,action_code,target_type,target_id,outcome_code,reason_code,request_id,occurred_at)
    SELECT ?,?,?,?,?,'SUCCEEDED',?,?,? WHERE changes()=1`).bind(crypto.randomUUID(), actor.accountId, actionCode, targetType, event.resourceId, event.reasonCode, requestId, occurredAt);
  const [result] = await db.batch([mutation, lifecycleEvent, audit]); return result.meta.changes ?? 0;
}

export async function getAdminLmsOverview(actor: AccountContext, offsets: AdminLmsOffsets): Promise<OperationResult<AdminLmsOverview>> {
  if (!await hasAnyFreshLmsPermission(actor.accountId)) return { ok: false, code: "PERMISSION_REQUIRED" };
  const db = requireDb(); const safe = { course: pageOffset(offsets.course), class: pageOffset(offsets.class), lesson: pageOffset(offsets.lesson), assignment: pageOffset(offsets.assignment), enrollment: pageOffset(offsets.enrollment) };
  const [courseRows, classRows, lessonRows, assignmentRows, enrollmentRows, instructorRows, studentRows] = await Promise.all([
    db.prepare(`SELECT course_id,title,course_status,version,activated_at,archived_at,updated_at FROM lms_courses WHERE EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL) ORDER BY created_at DESC,course_id LIMIT 26 OFFSET ?`).bind(actor.accountId, safe.course).all<{ course_id: string; title: string; course_status: CourseStatus; version: number; activated_at: string | null; archived_at: string | null; updated_at: string }>(),
    db.prepare(`SELECT c.class_id,c.course_id,c.title,c.class_status,c.version,c.activated_at,c.closed_at,c.updated_at,o.title AS course_title FROM lms_classes c JOIN lms_courses o ON o.course_id=c.course_id WHERE EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='classes.manage' AND p.revoked_at IS NULL) ORDER BY c.created_at DESC,c.class_id LIMIT 26 OFFSET ?`).bind(actor.accountId, safe.class).all<{ class_id: string; course_id: string; title: string; class_status: ClassStatus; version: number; activated_at: string | null; closed_at: string | null; updated_at: string; course_title: string }>(),
    db.prepare(`SELECT l.lesson_id,l.course_id,l.title,l.body_text,l.position,l.lesson_status,l.version,l.published_at,l.archived_at,l.published_revision_id,l.updated_at,c.title AS course_title FROM lms_lessons l JOIN lms_courses c ON c.course_id=l.course_id WHERE EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL) ORDER BY l.updated_at DESC,l.lesson_id LIMIT 26 OFFSET ?`).bind(actor.accountId, safe.lesson).all<{ lesson_id: string; course_id: string; title: string; body_text: string; position: number; lesson_status: LessonStatus; version: number; published_at: string | null; archived_at: string | null; published_revision_id: string | null; updated_at: string; course_title: string }>(),
    db.prepare(`SELECT ia.assignment_id,ia.class_id,ia.instructor_account_id,ia.assigned_at FROM lms_class_instructor_assignments ia WHERE ia.revoked_at IS NULL AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='classes.assign_instructor' AND p.revoked_at IS NULL) ORDER BY ia.assigned_at DESC,ia.assignment_id LIMIT 26 OFFSET ?`).bind(actor.accountId, safe.assignment).all<{ assignment_id: string; class_id: string; instructor_account_id: string; assigned_at: string }>(),
    db.prepare(`SELECT e.enrollment_id,e.class_id,e.student_account_id,e.enrollment_status,e.version,e.completed_at,e.withdrawn_at,e.updated_at FROM lms_enrollments e WHERE EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='enrollments.manage' AND p.revoked_at IS NULL) ORDER BY e.updated_at DESC,e.enrollment_id LIMIT 26 OFFSET ?`).bind(actor.accountId, safe.enrollment).all<{ enrollment_id: string; class_id: string; student_account_id: string; enrollment_status: EnrollmentStatus; version: number; completed_at: string | null; withdrawn_at: string | null; updated_at: string }>(),
    db.prepare(`SELECT DISTINCT a.account_id FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id WHERE a.account_status='ACTIVE' AND r.role_code='INSTRUCTOR' AND r.revoked_at IS NULL AND EXISTS (SELECT 1 FROM accounts aa JOIN role_assignments ar ON ar.account_id=aa.account_id JOIN permission_grants p ON p.account_id=aa.account_id WHERE aa.account_id=? AND aa.account_status='ACTIVE' AND ar.role_code='ADMIN' AND ar.revoked_at IS NULL AND p.permission_code='classes.assign_instructor' AND p.revoked_at IS NULL) ORDER BY a.account_id LIMIT 250`).bind(actor.accountId).all<{ account_id: string }>(),
    db.prepare(`SELECT DISTINCT a.account_id FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id WHERE a.account_status='ACTIVE' AND a.adult_confirmed=1 AND r.role_code='ADULT_STUDENT' AND r.revoked_at IS NULL AND EXISTS (SELECT 1 FROM accounts aa JOIN role_assignments ar ON ar.account_id=aa.account_id JOIN permission_grants p ON p.account_id=aa.account_id WHERE aa.account_id=? AND aa.account_status='ACTIVE' AND ar.role_code='ADMIN' AND ar.revoked_at IS NULL AND p.permission_code='enrollments.manage' AND p.revoked_at IS NULL) ORDER BY a.account_id LIMIT 250`).bind(actor.accountId).all<{ account_id: string }>(),
  ]);
  const courses = courseRows.results.slice(0, 25); const classes = classRows.results.slice(0, 25); const lessons = lessonRows.results.slice(0, 25); const assignments = assignmentRows.results.slice(0, 25); const enrollments = enrollmentRows.results.slice(0, 25);
  return { ok: true, value: {
    courses: courses.map((r) => ({ courseId: r.course_id, title: r.title, status: r.course_status, version: r.version, activatedAt: r.activated_at, archivedAt: r.archived_at, updatedAt: r.updated_at })),
    classes: classes.map((r) => ({ classId: r.class_id, courseId: r.course_id, title: r.title, status: r.class_status, version: r.version, activatedAt: r.activated_at, closedAt: r.closed_at, updatedAt: r.updated_at, courseTitle: r.course_title })),
    lessons: lessons.map((r) => ({ lessonId: r.lesson_id, courseId: r.course_id, title: r.title, bodyText: r.body_text, position: r.position, status: r.lesson_status, version: r.version, publishedAt: r.published_at, archivedAt: r.archived_at, publishedRevisionId: r.published_revision_id, updatedAt: r.updated_at, courseTitle: r.course_title })),
    assignments: assignments.map((r) => ({ assignmentId: r.assignment_id, classId: r.class_id, instructorAccountId: r.instructor_account_id, assignedAt: r.assigned_at, version: 1 })),
    enrollments: enrollments.map((r) => ({ enrollmentId: r.enrollment_id, classId: r.class_id, studentAccountId: r.student_account_id, status: r.enrollment_status, version: r.version, completedAt: r.completed_at, withdrawnAt: r.withdrawn_at, updatedAt: r.updated_at })),
    instructors: instructorRows.results.map((r) => ({ accountId: r.account_id })), students: studentRows.results.map((r) => ({ accountId: r.account_id })),
    nextCourseOffset: courseRows.results.length > 25 ? safe.course + 25 : null, nextClassOffset: classRows.results.length > 25 ? safe.class + 25 : null, nextLessonOffset: lessonRows.results.length > 25 ? safe.lesson + 25 : null,
    nextAssignmentOffset: assignmentRows.results.length > 25 ? safe.assignment + 25 : null, nextEnrollmentOffset: enrollmentRows.results.length > 25 ? safe.enrollment + 25 : null,
  } };
}

export async function createCourse(actor: AccountContext, input: { title: string }, requestId: string): Promise<OperationResult<{ courseId: string }>> {
  const courseId = crypto.randomUUID(); const now = new Date().toISOString(); const db = requireDb();
  const mutation = db.prepare(`INSERT INTO lms_courses (course_id,audience,title,course_status,version,created_by_account_id,created_at,updated_at) SELECT ?,'ADULT_ONLY',?,'DRAFT',1,a.account_id,?,? FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL`).bind(courseId, input.title, now, now, actor.accountId);
  const changes = await runLifecycleMutation(db, mutation, actor, { resourceType: "COURSE", resourceId: courseId, fromStatus: null, toStatus: "DRAFT", reasonCode: "RESOURCE_CREATED", version: 1 }, "lms.course.create", "LMS_COURSE", requestId, now);
  return changes === 1 ? { ok: true, value: { courseId } } : { ok: false, code: "PERMISSION_REQUIRED" };
}
export async function updateCourse(actor: AccountContext, courseId: string, input: { title: string; expectedVersion: number }, requestId: string): Promise<OperationResult> {
  if (!isLmsId(courseId)) return { ok: false, code: "INVALID_TARGET_ID" }; if (!await hasFreshPermission(actor.accountId, "courses.manage")) return { ok: false, code: "PERMISSION_REQUIRED" };
  const db = requireDb(); const now = new Date().toISOString(); const mutation = db.prepare(`UPDATE lms_courses SET title=?,version=version+1,updated_at=? WHERE course_id=? AND version=? AND course_status<>'ARCHIVED' AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(input.title, now, courseId, input.expectedVersion, actor.accountId);
  const changes = await runAuditedMutation(db, mutation, actor, "lms.course.content_update", "LMS_COURSE", courseId, "CONTENT_UPDATED", requestId, now); return changes === 1 ? { ok: true, value: undefined } : { ok: false, code: "VERSION_CONFLICT" };
}
export async function transitionCourse(actor: AccountContext, courseId: string, input: { toStatus: CourseStatus; expectedVersion: number; reasonCode: LifecycleReasonCode }, requestId: string): Promise<OperationResult> {
  if (!isLmsId(courseId)) return { ok: false, code: "INVALID_TARGET_ID" }; const db = requireDb();
  const state = await db.prepare(`SELECT c.course_status,c.version FROM lms_courses c WHERE c.course_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(courseId, actor.accountId).first<{ course_status: CourseStatus; version: number }>();
  if (!state) return { ok: false, code: "COURSE_TRANSITION_DENIED" }; if (state.version !== input.expectedVersion) return { ok: false, code: "VERSION_CONFLICT" };
  const allowed = (state.course_status === "DRAFT" && (input.toStatus === "ACTIVE" || input.toStatus === "ARCHIVED")) || (state.course_status === "ACTIVE" && (input.toStatus === "DRAFT" || input.toStatus === "ARCHIVED")); if (!allowed || !isTransitionReasonAllowed("COURSE", state.course_status, input.toStatus, input.reasonCode)) return { ok: false, code: "INVALID_TRANSITION" };
  if (input.toStatus === "ARCHIVED") { const openClass = await db.prepare("SELECT 1 AS blocked FROM lms_classes WHERE course_id=? AND class_status<>'CLOSED' LIMIT 1").bind(courseId).first<{ blocked: number }>(); if (openClass) return { ok: false, code: "COURSE_HAS_OPEN_CLASSES" }; }
  const now = new Date().toISOString(); const mutation = db.prepare(`UPDATE lms_courses SET course_status=?,version=version+1,activated_at=CASE WHEN ?='ACTIVE' THEN ? ELSE NULL END,archived_at=CASE WHEN ?='ARCHIVED' THEN ? ELSE NULL END,updated_at=? WHERE course_id=? AND version=? AND ((course_status='DRAFT' AND (?='ACTIVE' OR ?='ARCHIVED')) OR (course_status='ACTIVE' AND (?='DRAFT' OR ?='ARCHIVED'))) AND (?<>'ARCHIVED' OR NOT EXISTS (SELECT 1 FROM lms_classes c WHERE c.course_id=lms_courses.course_id AND c.class_status<>'CLOSED')) AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(input.toStatus, input.toStatus, now, input.toStatus, now, now, courseId, input.expectedVersion, input.toStatus, input.toStatus, input.toStatus, input.toStatus, input.toStatus, actor.accountId);
  const changes = await runLifecycleMutation(db, mutation, actor, { resourceType: "COURSE", resourceId: courseId, fromStatus: state.course_status, toStatus: input.toStatus, reasonCode: input.reasonCode, version: state.version + 1 }, "lms.course.transition", "LMS_COURSE", requestId, now); return changes === 1 ? { ok: true, value: undefined } : { ok: false, code: "VERSION_CONFLICT" };
}

export async function createLesson(actor: AccountContext, courseId: string, input: { title: string; bodyText: string; position: number }, requestId: string): Promise<OperationResult<{ lessonId: string }>> {
  if (!isLmsId(courseId)) return { ok: false, code: "INVALID_TARGET_ID" }; const lessonId = crypto.randomUUID(); const now = new Date().toISOString(); const db = requireDb();
  try { const mutation = db.prepare(`INSERT INTO lms_lessons (lesson_id,course_id,title,body_text,position,lesson_status,version,created_by_account_id,created_at,updated_at) SELECT ?,c.course_id,?,?,?,'DRAFT',1,?,?,? FROM lms_courses c WHERE c.course_id=? AND c.course_status<>'ARCHIVED' AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(lessonId, input.title, input.bodyText, input.position, actor.accountId, now, now, courseId, actor.accountId);
    const changes = await runLifecycleMutation(db, mutation, actor, { resourceType: "LESSON", resourceId: lessonId, fromStatus: null, toStatus: "DRAFT", reasonCode: "RESOURCE_CREATED", version: 1 }, "lms.lesson.create", "LMS_LESSON", requestId, now); return changes === 1 ? { ok: true, value: { lessonId } } : { ok: false, code: "LESSON_CREATE_DENIED" };
  } catch { return { ok: false, code: "LESSON_POSITION_CONFLICT" }; }
}
export async function updateLesson(actor: AccountContext, lessonId: string, input: { position: number; expectedVersion: number }, requestId: string): Promise<OperationResult> {
  if (!isLmsId(lessonId)) return { ok: false, code: "INVALID_TARGET_ID" }; if (!await hasFreshPermission(actor.accountId, "courses.manage")) return { ok: false, code: "PERMISSION_REQUIRED" };
  try { const db = requireDb(); const now = new Date().toISOString(); const mutation = db.prepare(`UPDATE lms_lessons SET position=?,version=version+1,updated_at=? WHERE lesson_id=? AND version=? AND lesson_status<>'ARCHIVED' AND EXISTS (SELECT 1 FROM lms_courses c WHERE c.course_id=lms_lessons.course_id AND c.course_status<>'ARCHIVED') AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(input.position, now, lessonId, input.expectedVersion, actor.accountId);
    const changes = await runAuditedMutation(db, mutation, actor, "lms.lesson.content_update", "LMS_LESSON", lessonId, "CONTENT_UPDATED", requestId, now); return changes === 1 ? { ok: true, value: undefined } : { ok: false, code: "VERSION_CONFLICT" };
  } catch { return { ok: false, code: "LESSON_POSITION_CONFLICT" }; }
}
export async function transitionLesson(actor: AccountContext, lessonId: string, input: { toStatus: LessonStatus; expectedVersion: number; reasonCode: LifecycleReasonCode }, requestId: string): Promise<OperationResult> {
  if (!isLmsId(lessonId)) return { ok: false, code: "INVALID_TARGET_ID" }; const db = requireDb(); const state = await db.prepare(`SELECT l.lesson_status,l.version,l.published_revision_id FROM lms_lessons l WHERE l.lesson_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(lessonId, actor.accountId).first<{ lesson_status: LessonStatus; version: number; published_revision_id: string | null }>();
  if (!state) return { ok: false, code: "LESSON_TRANSITION_DENIED" }; if (state.version !== input.expectedVersion) return { ok: false, code: "VERSION_CONFLICT" }; if (state.lesson_status === "DRAFT" && input.toStatus === "PUBLISHED" && !state.published_revision_id) return { ok: false, code: "PUBLISHED_REVISION_REQUIRED" }; const allowed = (state.lesson_status === "DRAFT" && (input.toStatus === "PUBLISHED" || input.toStatus === "ARCHIVED")) || (state.lesson_status === "PUBLISHED" && (input.toStatus === "DRAFT" || input.toStatus === "ARCHIVED")); if (!allowed || !isTransitionReasonAllowed("LESSON", state.lesson_status, input.toStatus, input.reasonCode)) return { ok: false, code: "INVALID_TRANSITION" };
  const now = new Date().toISOString(); const mutation = db.prepare(`UPDATE lms_lessons SET lesson_status=?,version=version+1,published_at=CASE WHEN ?='PUBLISHED' THEN ? ELSE NULL END,archived_at=CASE WHEN ?='ARCHIVED' THEN ? ELSE NULL END,updated_at=? WHERE lesson_id=? AND version=? AND ((lesson_status='DRAFT' AND (?='PUBLISHED' OR ?='ARCHIVED')) OR (lesson_status='PUBLISHED' AND (?='DRAFT' OR ?='ARCHIVED'))) AND (?<>'PUBLISHED' OR (published_revision_id IS NOT NULL AND EXISTS (SELECT 1 FROM lms_courses c WHERE c.course_id=lms_lessons.course_id AND c.course_status<>'ARCHIVED'))) AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(input.toStatus, input.toStatus, now, input.toStatus, now, now, lessonId, input.expectedVersion, input.toStatus, input.toStatus, input.toStatus, input.toStatus, input.toStatus, actor.accountId);
  const changes = await runLifecycleMutation(db, mutation, actor, { resourceType: "LESSON", resourceId: lessonId, fromStatus: state.lesson_status, toStatus: input.toStatus, reasonCode: input.reasonCode, version: state.version + 1 }, "lms.lesson.transition", "LMS_LESSON", requestId, now); return changes === 1 ? { ok: true, value: undefined } : { ok: false, code: "VERSION_CONFLICT" };
}

export async function createLessonRevision(actor: AccountContext, lessonId: string, input: { title: string; bodyText: string }, requestId: string): Promise<OperationResult<{ revisionId: string }>> {
  if (!isLmsId(lessonId) || !await hasFreshPermission(actor.accountId, "courses.manage")) return { ok: false, code: "PERMISSION_REQUIRED" };
  const db = requireDb(); const revisionId = crypto.randomUUID(); const now = new Date().toISOString();
  const mutation = db.prepare(`INSERT INTO lms_lesson_revisions (revision_id,lesson_id,title,body_text,created_by_account_id,created_at) SELECT ?,l.lesson_id,?,?,?,? FROM lms_lessons l JOIN lms_courses c ON c.course_id=l.course_id WHERE l.lesson_id=? AND l.lesson_status<>'ARCHIVED' AND c.course_status<>'ARCHIVED' AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments r ON r.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND r.role_code='ADMIN' AND r.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(revisionId, input.title, input.bodyText, actor.accountId, now, lessonId, actor.accountId);
  const changes = await runAuditedMutation(db, mutation, actor, "lms.lesson.revision.create", "LMS_LESSON_REVISION", revisionId, "CONTENT_UPDATED", requestId, now);
  return changes === 1 ? { ok: true, value: { revisionId } } : { ok: false, code: "REVISION_CREATE_DENIED" };
}

export async function listLessonRevisions(actor: AccountContext, lessonId: string, offset: number): Promise<OperationResult<{ lesson: LmsLesson; revisions: LessonRevision[]; nextOffset: number | null }>> {
  if (!isLmsId(lessonId)) return { ok: false, code: "INVALID_TARGET_ID" };
  const safe = pageOffset(offset); const db = requireDb();
  const lesson = await db.prepare(`SELECT l.lesson_id,l.course_id,l.title,l.body_text,l.position,l.lesson_status,l.version,l.published_at,l.archived_at,l.published_revision_id,l.updated_at FROM lms_lessons l WHERE l.lesson_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments ra ON ra.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND ra.role_code='ADMIN' AND ra.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(lessonId, actor.accountId).first<{ lesson_id: string; course_id: string; title: string; body_text: string; position: number; lesson_status: LessonStatus; version: number; published_at: string | null; archived_at: string | null; published_revision_id: string | null; updated_at: string }>();
  if (!lesson) return { ok: false, code: "LESSON_NOT_FOUND_OR_DENIED" };
  const rows = await db.prepare(`SELECT r.revision_id,r.lesson_id,r.title,r.body_text,r.created_by_account_id,r.created_at,(SELECT MAX(pu.published_at) FROM lms_lesson_publications pu WHERE pu.lesson_id=r.lesson_id AND pu.revision_id=r.revision_id) AS last_published_at FROM lms_lesson_revisions r WHERE r.lesson_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments ra ON ra.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND ra.role_code='ADMIN' AND ra.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL) ORDER BY r.created_at DESC,r.revision_id DESC LIMIT 26 OFFSET ?`).bind(lessonId, actor.accountId, safe).all<{ revision_id: string; lesson_id: string; title: string; body_text: string; created_by_account_id: string; created_at: string; last_published_at: string | null }>();
  if (!await hasFreshPermission(actor.accountId, "courses.manage")) return { ok: false, code: "PERMISSION_REQUIRED" };
  return { ok: true, value: { lesson: { lessonId: lesson.lesson_id, courseId: lesson.course_id, title: lesson.title, bodyText: lesson.body_text, position: lesson.position, status: lesson.lesson_status, version: lesson.version, publishedAt: lesson.published_at, archivedAt: lesson.archived_at, publishedRevisionId: lesson.published_revision_id, updatedAt: lesson.updated_at }, revisions: rows.results.slice(0, 25).map((r) => ({ revisionId: r.revision_id, lessonId: r.lesson_id, title: r.title, bodyText: r.body_text, createdByAccountId: r.created_by_account_id, createdAt: r.created_at, lastPublishedAt: r.last_published_at })), nextOffset: rows.results.length > 25 ? safe + 25 : null } };
}

export async function publishLessonRevision(actor: AccountContext, lessonId: string, revisionId: string, input: { expectedLessonVersion: number; reasonCode: "CONTENT_UPDATE"|"CONTENT_ROLLBACK" }, requestId: string): Promise<OperationResult> {
  if (!isLmsId(lessonId) || !isLmsId(revisionId)) return { ok: false, code: "INVALID_TARGET_ID" };
  const db = requireDb();
  const state = await db.prepare(`SELECT l.version,l.lesson_status,l.published_revision_id,c.course_status,EXISTS (SELECT 1 FROM lms_lesson_revisions lr WHERE lr.revision_id=? AND lr.lesson_id=l.lesson_id) AS owns_revision,EXISTS (SELECT 1 FROM lms_lesson_publications pu WHERE pu.lesson_id=l.lesson_id AND pu.revision_id=?) AS was_published FROM lms_lessons l JOIN lms_courses c ON c.course_id=l.course_id WHERE l.lesson_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments ra ON ra.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND ra.role_code='ADMIN' AND ra.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(revisionId, revisionId, lessonId, actor.accountId).first<{ version: number; lesson_status: LessonStatus; published_revision_id: string | null; course_status: CourseStatus; owns_revision: number; was_published: number }>();
  if (!state || state.lesson_status === "ARCHIVED" || state.course_status === "ARCHIVED" || state.owns_revision !== 1) return { ok: false, code: "REVISION_PUBLISH_DENIED" };
  if (state.version !== input.expectedLessonVersion) return { ok: false, code: "VERSION_CONFLICT" };
  if (state.published_revision_id === revisionId) return { ok: false, code: "REVISION_ALREADY_PUBLISHED" };
  const expectedReason = state.was_published === 1 ? "CONTENT_ROLLBACK" : "CONTENT_UPDATE";
  if (input.reasonCode !== expectedReason) return { ok: false, code: "INVALID_PUBLICATION_REASON" };
  const now = new Date().toISOString();
  const mutation = db.prepare(`UPDATE lms_lessons SET published_revision_id=?,title=(SELECT title FROM lms_lesson_revisions WHERE revision_id=? AND lesson_id=?),body_text=(SELECT body_text FROM lms_lesson_revisions WHERE revision_id=? AND lesson_id=?),version=version+1,updated_at=? WHERE lesson_id=? AND version=? AND lesson_status<>'ARCHIVED' AND EXISTS (SELECT 1 FROM lms_courses c WHERE c.course_id=lms_lessons.course_id AND c.course_status<>'ARCHIVED') AND EXISTS (SELECT 1 FROM lms_lesson_revisions r WHERE r.revision_id=? AND r.lesson_id=lms_lessons.lesson_id) AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments ra ON ra.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND ra.role_code='ADMIN' AND ra.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(revisionId, revisionId, lessonId, revisionId, lessonId, now, lessonId, input.expectedLessonVersion, revisionId, actor.accountId);
  const publication = db.prepare(`INSERT INTO lms_lesson_publications (publication_id,lesson_id,revision_id,lesson_version,reason_code,published_by_account_id,published_at) SELECT ?,?,?,?,?,?,? WHERE changes()=1`).bind(crypto.randomUUID(), lessonId, revisionId, input.expectedLessonVersion + 1, input.reasonCode, actor.accountId, now);
  const audit = db.prepare(`INSERT INTO audit_events (audit_event_id,actor_account_id,action_code,target_type,target_id,outcome_code,reason_code,request_id,occurred_at) SELECT ?,?,'lms.lesson.revision.publish','LMS_LESSON',?,'SUCCEEDED',?,?,? WHERE changes()=1`).bind(crypto.randomUUID(), actor.accountId, lessonId, input.reasonCode, requestId, now);
  const [result] = await db.batch([mutation, publication, audit]);
  if ((result.meta.changes ?? 0) === 1) return { ok: true, value: undefined };
  const fresh = await db.prepare(`SELECT l.version FROM lms_lessons l WHERE l.lesson_id=? AND EXISTS (SELECT 1 FROM accounts a JOIN role_assignments ra ON ra.account_id=a.account_id JOIN permission_grants p ON p.account_id=a.account_id WHERE a.account_id=? AND a.account_status='ACTIVE' AND ra.role_code='ADMIN' AND ra.revoked_at IS NULL AND p.permission_code='courses.manage' AND p.revoked_at IS NULL)`).bind(lessonId, actor.accountId).first<{ version: number }>();
  if (fresh && fresh.version !== input.expectedLessonVersion) return { ok: false, code: "VERSION_CONFLICT" };
  return { ok: false, code: "REVISION_PUBLISH_DENIED" };
}

